diff --git a/src/runner/telemetry.rs b/src/runner/telemetry.rs
index ae4f56c..999ef88 100644
--- a/src/runner/telemetry.rs
+++ b/src/runner/telemetry.rs
@@ -407,4 +407,381 @@ mod tests {
         assert!(scrubbed.contains("[PATH]"));
         assert!(!scrubbed.contains("/home/user"));
     }
+
+    #[test]
+    fn scrub_removes_tmp_paths() {
+        let input = "wrote to /tmp/bivvy-build-12345/output.log";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(!scrubbed.contains("/tmp/"));
+    }
+
+    #[test]
+    fn scrub_removes_windows_paths() {
+        let input = r"Error at C:\Users\brenna\project\main.rs";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(!scrubbed.contains(r"C:\Users\brenna"));
+    }
+
+    #[test]
+    fn scrub_removes_xoxb_slack_tokens() {
+        let input = "token: xoxb-123456789-abcdefghij";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("xoxb-"));
+    }
+
+    #[test]
+    fn scrub_removes_xoxp_slack_tokens() {
+        let input = "token: xoxp-999888777-abcdefghij";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("xoxp-"));
+    }
+
+    #[test]
+    fn scrub_removes_gho_tokens() {
+        let input = "oauth: gho_abcdefghijklmnopqrstuvwxyz1234567890";
+        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
+        assert!(scrubbed.contains("[REDACTED]"));
+        assert!(!scrubbed.contains("gho_"));
+    }
+
+    #[test]
+    fn scrub_handles_empty_input() {
+        let scrubbed = scrub_for_telemetry("", &HashMap::new());
+        assert_eq!(scrubbed, "");
+    }
+
+    #[test]
+    fn scrub_handles_multiple_secrets_in_env() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "key-aaa".to_string());
+        env.insert("SECRET".to_string(), "secret-bbb".to_string());
+
+        let input = "failed: key-aaa and secret-bbb exposed";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert!(!scrubbed.contains("key-aaa"));
+        assert!(!scrubbed.contains("secret-bbb"));
+    }
+
+    #[test]
+    fn scrub_ignores_non_secret_env_vars() {
+        let mut env = HashMap::new();
+        env.insert("PATH".to_string(), "/usr/bin".to_string());
+        env.insert("HOME".to_string(), "/Users/brenna".to_string());
+        env.insert("NODE_ENV".to_string(), "production".to_string());
+
+        let input = "NODE_ENV is production";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert!(scrubbed.contains("production"));
+    }
+
+    #[test]
+    fn scrub_ignores_empty_env_values() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "".to_string());
+
+        let input = "nothing secret here";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert_eq!(scrubbed, "nothing secret here");
+    }
+
+    #[test]
+    fn scrub_combines_env_path_and_token_scrubbing() {
+        let mut env = HashMap::new();
+        env.insert("API_KEY".to_string(), "my-secret-key".to_string());
+
+        let input =
+            "error: my-secret-key at /Users/brenna/project with ghp_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
+        let scrubbed = scrub_for_telemetry(input, &env);
+        assert!(!scrubbed.contains("my-secret-key"));
+        assert!(!scrubbed.contains("/Users/brenna"));
+        assert!(!scrubbed.contains("ghp_"));
+        assert!(scrubbed.contains("[PATH]"));
+        assert!(scrubbed.contains("[REDACTED]"));
+    }
+
+    #[test]
+    fn scrub_at_exact_max_length_does_not_truncate() {
+        // Use "." which won't match any token/path regex
+        let input: String = ".".repeat(MAX_ERROR_LENGTH);
+        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
+        assert_eq!(scrubbed.len(), MAX_ERROR_LENGTH);
+        assert!(!scrubbed.ends_with("...[truncated]"));
+    }
+
+    #[test]
+    fn scrub_one_over_max_length_truncates() {
+        let input: String = ".".repeat(MAX_ERROR_LENGTH + 1);
+        let scrubbed = scrub_for_telemetry(&input, &HashMap::new());
+        assert!(scrubbed.ends_with("...[truncated]"));
+    }
+
+    #[test]
+    fn consent_display_all_variants() {
+        assert_eq!(TelemetryConsent::Send.to_string(), "send");
+        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
+        assert_eq!(TelemetryConsent::Always.to_string(), "always");
+        assert_eq!(TelemetryConsent::Never.to_string(), "never");
+    }
+
+    #[test]
+    fn build_report_with_none_exit_code() {
+        let report = build_report("test", "echo hi", None, "output", "retry", &HashMap::new());
+        assert_eq!(report.exit_code, None);
+    }
+
+    #[test]
+    fn build_report_scrubs_command_field() {
+        let mut env = HashMap::new();
+        env.insert("TOKEN".to_string(), "secret123".to_string());
+
+        let report = build_report(
+            "deploy",
+            "curl -H 'Auth: secret123' https://api.example.com",
+            Some(1),
+            "",
+            "retry",
+            &env,
+        );
+
+        assert!(!report.command_scrubbed.contains("secret123"));
+    }
+
+    #[test]
+    fn build_report_scrubs_paths_in_command() {
+        let report = build_report(
+            "build",
+            "gcc /Users/brenna/project/main.c -o out",
+            Some(1),
+            "",
+            "retry",
+            &HashMap::new(),
+        );
+
+        assert!(!report.command_scrubbed.contains("/Users/brenna"));
+        assert!(report.command_scrubbed.contains("[PATH]"));
+    }
+
+    #[test]
+    fn prompt_telemetry_returns_always_from_ui() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "always");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::Always);
+    }
+
+    #[test]
+    fn prompt_telemetry_returns_never_from_ui() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "never");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::Never);
+    }
+
+    #[test]
+    fn prompt_telemetry_defaults_to_no_thanks_for_unknown_answer() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "garbage");
+
+        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
+        assert_eq!(result, TelemetryConsent::NoThanks);
+    }
+
+    #[test]
+    fn prompt_telemetry_ignores_unknown_saved_preference() {
+        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "send");
+
+        // "garbage" saved preference should not short-circuit, should prompt
+        let result = prompt_telemetry(&mut ui, &report, Some("garbage")).unwrap();
+        assert_eq!(result, TelemetryConsent::Send);
+        assert_eq!(ui.prompts_shown().len(), 1);
+    }
+
+    #[test]
+    fn prompt_telemetry_displays_step_name_in_messages() {
+        let report = build_report(
+            "bundler",
+            "bundle install",
+            Some(1),
+            "gem error",
+            "shell → retry",
+            &HashMap::new(),
+        );
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
+        assert!(ui.has_message("bundler"));
+        assert!(ui.has_message("bundle install"));
+        assert!(ui.has_message("gem error"));
+        assert!(ui.has_message("shell → retry"));
+    }
+
+    #[test]
+    fn prompt_telemetry_displays_exit_code() {
+        let report = build_report(
+            "test",
+            "cargo test",
+            Some(101),
+            "",
+            "retry",
+            &HashMap::new(),
+        );
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
+        assert!(ui.has_message("101"));
+    }
+
+    #[test]
+    fn prompt_telemetry_skips_exit_code_when_none() {
+        let report = build_report("test", "cargo test", None, "err", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
+        assert!(!ui.messages().iter().any(|m| m.contains("Exit:")));
+    }
+
+    #[test]
+    fn prompt_telemetry_skips_error_when_empty() {
+        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
+        let mut ui = crate::ui::MockUI::new();
+        ui.set_interactive(true);
+        ui.set_prompt_response("telemetry_failure", "no_thanks");
+
+        prompt_telemetry(&mut ui, &report, None).unwrap();
+
+        assert!(!ui.messages().iter().any(|m| m.contains("Error:")));
+    }
+
+    #[test]
+    fn save_report_to_creates_directory() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let nested = temp.path().join("deep").join("nested");
+
+        let report = build_report("test", "echo", Some(0), "", "retry", &HashMap::new());
+        let path = save_report_to(&report, &nested).unwrap();
+
+        assert!(nested.exists());
+        assert!(path.exists());
+    }
+
+    #[test]
+    fn save_report_to_filename_contains_step_name() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let report = build_report(
+            "bundler",
+            "bundle install",
+            Some(1),
+            "",
+            "retry",
+            &HashMap::new(),
+        );
+
+        let path = save_report_to(&report, temp.path()).unwrap();
+        let filename = path.file_name().unwrap().to_str().unwrap();
+
+        assert!(filename.ends_with("-bundler.yml"));
+    }
+
+    #[test]
+    fn save_report_to_produces_valid_yaml_roundtrip() {
+        let temp = tempfile::TempDir::new().unwrap();
+        let report = build_report(
+            "cargo",
+            "cargo build",
+            Some(101),
+            "compilation failed",
+            "shell → retry",
+            &HashMap::new(),
+        );
+
+        let path = save_report_to(&report, temp.path()).unwrap();
+        let content = std::fs::read_to_string(&path).unwrap();
+        let deserialized: FailureReport = serde_yaml::from_str(&content).unwrap();
+
+        assert_eq!(deserialized.step_name, "cargo");
+        assert_eq!(deserialized.command_scrubbed, "cargo build");
+        assert_eq!(deserialized.exit_code, Some(101));
+        assert_eq!(deserialized.error_scrubbed, "compilation failed");
+        assert_eq!(deserialized.recovery_action, "shell → retry");
+    }
+
+    #[test]
+    fn reports_dir_is_under_bivvy() {
+        let dir = reports_dir();
+        let path_str = dir.to_str().unwrap();
+        assert!(path_str.contains(".bivvy"));
+        assert!(path_str.ends_with("failure-reports"));
+    }
+
+    #[test]
+    fn failure_report_serde_roundtrip() {
+        let report = FailureReport {
+            step_name: "test-step".to_string(),
+            command_scrubbed: "make build".to_string(),
+            exit_code: Some(2),
+            error_scrubbed: "error output".to_string(),
+            recovery_action: "retry".to_string(),
+            bivvy_version: "1.0.0".to_string(),
+            platform: "linux-x86_64".to_string(),
+        };
+
+        let yaml = serde_yaml::to_string(&report).unwrap();
+        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();
+
+        assert_eq!(deserialized.step_name, report.step_name);
+        assert_eq!(deserialized.command_scrubbed, report.command_scrubbed);
+        assert_eq!(deserialized.exit_code, report.exit_code);
+        assert_eq!(deserialized.error_scrubbed, report.error_scrubbed);
+        assert_eq!(deserialized.recovery_action, report.recovery_action);
+        assert_eq!(deserialized.bivvy_version, report.bivvy_version);
+        assert_eq!(deserialized.platform, report.platform);
+    }
+
+    #[test]
+    fn failure_report_serde_with_none_exit_code() {
+        let report = FailureReport {
+            step_name: "step".to_string(),
+            command_scrubbed: "cmd".to_string(),
+            exit_code: None,
+            error_scrubbed: "".to_string(),
+            recovery_action: "skip".to_string(),
+            bivvy_version: "1.0.0".to_string(),
+            platform: "macos-aarch64".to_string(),
+        };
+
+        let yaml = serde_yaml::to_string(&report).unwrap();
+        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();
+        assert_eq!(deserialized.exit_code, None);
+    }
+
+    #[test]
+    fn consent_variants_are_eq() {
+        assert_eq!(TelemetryConsent::Send, TelemetryConsent::Send);
+        assert_ne!(TelemetryConsent::Send, TelemetryConsent::NoThanks);
+        assert_ne!(TelemetryConsent::Always, TelemetryConsent::Never);
+    }
 }

